package com.alibaba.nacos.ai.service.mcp.storage;

import com.alibaba.nacos.api.exception.runtime.NacosDeserializationException;
import com.alibaba.nacos.common.utils.JacksonUtils;
import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;
import org.mockito.Mockito;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class McpJsonValidationSupportTest {

    private static final String CONTRACT_NAME = "test contract";

    @Test
    void testParseWrapsJacksonDeserializationFailure() {
        try (MockedStatic<JacksonUtils> jacksonMock = Mockito.mockStatic(JacksonUtils.class)) {
            jacksonMock.when(() -> JacksonUtils.toObj("{}", Object.class))
                .thenThrow(new NacosDeserializationException());
            assertThrows(IllegalArgumentException.class,
                () -> McpJsonValidationSupport.parseSingleValue("{}", CONTRACT_NAME));
        }
    }

    @Test
    void testRejectUnknownNonStringField() {
        Map<Object, Object> object = new LinkedHashMap<>();
        object.put(1, "value");
        assertThrows(IllegalArgumentException.class,
            () -> McpJsonValidationSupport.rejectUnknownFields(object,
                Collections.singleton("known"), CONTRACT_NAME));
    }

    @Test
    void testRequireIntegerSupportsIntegralTypes() {
        Map<String, Object> object = new LinkedHashMap<>();
        for (Number value : new Number[] {(byte) 1, (short) 2, 3, 4L}) {
            object.put("value", value);
            assertEquals(value.intValue(), McpJsonValidationSupport.requireInteger(object,
                "value", CONTRACT_NAME));
        }
        object.put("value", 1.0D);
        assertThrows(IllegalArgumentException.class,
            () -> McpJsonValidationSupport.requireInteger(object, "value", CONTRACT_NAME));
    }

    @Test
    void testRequireIntegerRejectsOutOfRangeLong() {
        Map<String, Object> object = new LinkedHashMap<>();
        object.put("value", (long) Integer.MAX_VALUE + 1L);
        assertThrows(IllegalArgumentException.class,
            () -> McpJsonValidationSupport.requireInteger(object, "value", CONTRACT_NAME));
        object.put("value", (long) Integer.MIN_VALUE - 1L);
        assertThrows(IllegalArgumentException.class,
            () -> McpJsonValidationSupport.requireInteger(object, "value", CONTRACT_NAME));
    }

    @Test
    void testStrictParserRejectsWhitespaceOnlyInput() {
        assertThrows(IllegalArgumentException.class,
            () -> McpJsonValidationSupport.parseSingleValue("   ", CONTRACT_NAME));
    }
}

import { describe, expect, it } from 'vitest';
import fs from 'fs';
import path from 'path';

const SOURCE = fs.readFileSync(path.resolve(__dirname, '../index.tsx'), 'utf-8');

describe('AgentSpec visibility authorization entry', () => {
  it('shows the entry only for the resource owner or a global administrator', () => {
    expect(SOURCE).toContain('const { globalAdmin, username } = useAuthStore();');
    expect(SOURCE).toContain('const canManageVisibility = globalAdmin || detail.owner === username;');
    expect(SOURCE).toContain('visibilityLabel={canManageVisibility');
    expect(SOURCE).toContain('onVisibilityClick={canManageVisibility');
  });

  it('keeps draft and lifecycle write operations guarded by resource write permission', () => {
    expect(SOURCE).toContain('const canWriteResource = detail.writable;');
    expect(SOURCE).toContain('{canWriteResource && selectedVersion && currentVersionStatus && (');
    expect(SOURCE).toContain('enableDisabled={enableToggling || !canWriteResource}');
    expect(SOURCE).toContain('scopeDisabled={scopeToggling || !canWriteResource}');
    expect(SOURCE).toContain('canWrite={canWriteResource}');
  });

  it('derives the visibility resource identity from the current detail page', () => {
    expect(SOURCE).toContain('<VisibilityAuthorizationDialog');
    expect(SOURCE).toContain('namespaceId={namespaceId}');
    expect(SOURCE).toContain('resourceType="agentspec"');
    expect(SOURCE).toContain('resourceName={agentSpecName}');
    expect(SOURCE).toContain('onSuccess={loadDetail}');
  });
});

