package com.alibaba.nacos.ai.service.mcp.storage;

import com.alibaba.nacos.api.exception.runtime.NacosDeserializationException;
import com.alibaba.nacos.common.utils.JacksonUtils;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;

import java.io.IOException;
import java.util.Map;
import java.util.Set;

/**
 * Shared strict JSON shape validation for MCP internal storage contracts.
 *
 * @author Nacos
 */
final class McpJsonValidationSupport {

    private static final JsonFactory STRICT_JSON_FACTORY = new JsonFactory()
        .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);

    private McpJsonValidationSupport() {
    }

    static Object parseSingleValue(String json, String contractName) {
        if (json == null) {
            throw new IllegalArgumentException(contractName + " JSON must not be empty");
        }
        validateSingleJsonValue(json, contractName);
        try {
            return JacksonUtils.toObj(json, Object.class);
        } catch (NacosDeserializationException e) {
            throw new IllegalArgumentException("Invalid " + contractName, e);
        }
    }

    static Map<?, ?> parseObject(String json, String contractName) {
        Object value = parseSingleValue(json, contractName);
        if (!(value instanceof Map)) {
            throw new IllegalArgumentException(contractName + " must be a JSON object");
        }
        return (Map<?, ?>) value;
    }

    static void rejectUnknownFields(Map<?, ?> object, Set<String> fields, String contractName) {
        for (Object field : object.keySet()) {
            if (!(field instanceof String) || !fields.contains(field)) {
                throw new IllegalArgumentException("Unknown " + contractName + " field: " + field);
            }
        }
    }

    static String requireText(Map<?, ?> object, String field, String contractName) {
        Object value = object.get(field);
        if (!(value instanceof String)) {
            throw new IllegalArgumentException(contractName + " " + field + " must be a string");
        }
        return (String) value;
    }

    static String optionalText(Map<?, ?> object, String field, String contractName) {
        if (!object.containsKey(field)) {
            return null;
        }
        return requireText(object, field, contractName);
    }

    static int requireInteger(Map<?, ?> object, String field, String contractName) {
        Object value = object.get(field);
        if (!(value instanceof Byte || value instanceof Short || value instanceof Integer
            || value instanceof Long)) {
            throw new IllegalArgumentException(contractName + " " + field + " must be an integer");
        }
        long result = ((Number) value).longValue();
        if (result < Integer.MIN_VALUE || result > Integer.MAX_VALUE) {
            throw new IllegalArgumentException(contractName + " " + field + " is out of range");
        }
        return (int) result;
    }

    private static void validateSingleJsonValue(String json, String contractName) {
        try (JsonParser parser = STRICT_JSON_FACTORY.createParser(json)) {
            if (parser.nextToken() == null) {
                throw new IllegalArgumentException(contractName + " JSON must not be empty");
            }
            parser.skipChildren();
            if (parser.nextToken() != null) {
                throw new IllegalArgumentException(contractName + " must contain one JSON value");
            }
        } catch (IOException e) {
            throw new IllegalArgumentException("Invalid " + contractName, e);
        }
    }
}

import { beforeEach, describe, expect, it, vi } from 'vitest';

const mockClient = {
  post: vi.fn(() => Promise.resolve({ data: 'ok' })),
  delete: vi.fn(() => Promise.resolve({ data: 'ok' })),
};

vi.mock('../client', () => ({ default: mockClient }));

const { authApi } = await import('../auth');

describe('auth visibility API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('grants visibility through the plugin-owned endpoint', async () => {
    const request = {
      namespaceId: 'public',
      resourceType: 'skill',
      resourceName: 'demo-skill',
      username: 'alice',
      action: 'r' as const,
    };

    await authApi.grantVisibility(request);

    expect(mockClient.post).toHaveBeenCalledWith('v3/auth/visibility', request);
  });

  it('revokes visibility through the plugin-owned endpoint', async () => {
    const request = {
      namespaceId: 'public',
      resourceType: 'agentspec',
      resourceName: 'demo-agent',
      username: 'alice',
      action: 'w' as const,
    };

    await authApi.revokeVisibility(request);

    expect(mockClient.delete).toHaveBeenCalledWith('v3/auth/visibility', {
      params: request,
    });
  });

  it('propagates validation failures from the visibility endpoint', async () => {
    const error = {
      response: {
        data: {
          code: 400,
          message: 'parameter validate error',
          data: "user 'missing-user' not found",
        },
      },
    };
    mockClient.post.mockRejectedValueOnce(error);

    await expect(authApi.grantVisibility({
      namespaceId: 'public',
      resourceType: 'skill',
      resourceName: 'demo-skill',
      username: 'missing-user',
      action: 'r',
    })).rejects.toBe(error);
  });

  it('propagates permission denial from the visibility endpoint', async () => {
    const error = {
      response: {
        data: {
          code: 403,
          message: 'access denied',
          data: 'No permission to manage visibility grants for resource: demo-agent',
        },
      },
    };
    mockClient.delete.mockRejectedValueOnce(error);

    await expect(authApi.revokeVisibility({
      namespaceId: 'public',
      resourceType: 'agentspec',
      resourceName: 'demo-agent',
      username: 'alice',
      action: 'w',
    })).rejects.toBe(error);
  });

  it('propagates unsupported-plugin errors without using role or permission endpoints', async () => {
    const error = {
      response: {
        data: {
          code: 500,
          message: 'server error',
          data: 'visibility grant management is unsupported in current runtime',
        },
      },
    };
    mockClient.post.mockRejectedValueOnce(error);

    await expect(authApi.grantVisibility({
      namespaceId: 'public',
      resourceType: 'skill',
      resourceName: 'demo-skill',
      username: 'alice',
      action: 'r',
    })).rejects.toBe(error);
    expect(mockClient.post).toHaveBeenCalledTimes(1);
    expect(mockClient.delete).not.toHaveBeenCalled();
  });
});

