package com.alibaba.nacos.ai.utils;

import com.alibaba.nacos.api.exception.api.NacosApiException;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

/**
 * Security tests: verify that {@link AgentSpecZipParser} is hardened against malicious Zip uploads.
 *
 * <p>Covers three attack vectors:
 * <ul>
 *   <li>Zip Slip (path-traversal attack): entry name contains "../" sequences</li>
 *   <li>Zip bomb (decompressed-size attack): decompressed total exceeds the configured limit</li>
 *   <li>Entry-count attack: too many entries inside a single zip</li>
 * </ul>
 *
 * @author nacos
 */
class AgentSpecZipParserSecurityTest {

    private static final String NAMESPACE_ID = "test-ns";

    private static final String VALID_MANIFEST = "{\"version\":\"1.0\",\"description\":\"test\","
        + "\"worker\":{\"suggested_name\":\"test-worker\"}}";

    // ---- Test 1: path-traversal attack (Zip Slip) ----

    @Test
    void testPathTraversalAttackShouldBeRejected() throws IOException {
        // Build a malicious zip containing a path-traversal entry.
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos, StandardCharsets.UTF_8)) {
            // Legitimate manifest.json.
            addZipEntry(zos, "manifest.json", VALID_MANIFEST.getBytes(StandardCharsets.UTF_8));
            // Malicious entry: path traversal.
            addZipEntry(zos, "../../etc/passwd", "root:x:0:0".getBytes(StandardCharsets.UTF_8));
        }
        byte[] zipBytes = baos.toByteArray();

        // Expectation: parsing should fail and reject the traversal entry.
        try {
            AgentSpecZipParser.parseAgentSpecFromZip(zipBytes, NAMESPACE_ID);
            fail(
                "Expected the path-traversal zip to be rejected, but parsing succeeded (security hole!)");
        } catch (SecurityException | NacosApiException e) {
            // Expected: traversal rejected.
            System.out
                .println("[PASS] Path-traversal attack correctly rejected: " + e.getMessage());
        }
    }

    @Test
    void testAbsolutePathEntryShouldBeRejected() throws IOException {
        // Build a malicious zip containing an absolute-path entry.
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos, StandardCharsets.UTF_8)) {
            addZipEntry(zos, "manifest.json", VALID_MANIFEST.getBytes(StandardCharsets.UTF_8));
            // Malicious entry: absolute path.
            addZipEntry(zos, "/etc/shadow", "malicious".getBytes(StandardCharsets.UTF_8));
        }
        byte[] zipBytes = baos.toByteArray();

        try {
            AgentSpecZipParser.parseAgentSpecFromZip(zipBytes, NAMESPACE_ID);
            fail(
                "Expected the absolute-path zip to be rejected, but parsing succeeded (security hole!)");
        } catch (SecurityException | NacosApiException e) {
            System.out.println("[PASS] Absolute-path attack correctly rejected: " + e.getMessage());
        }
    }

    @Test
    void testWindowsDrivePathEntryShouldBeRejected() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos, StandardCharsets.UTF_8)) {
            addZipEntry(zos, "manifest.json", VALID_MANIFEST.getBytes(StandardCharsets.UTF_8));
            addZipEntry(zos, "C:/windows/system.ini", "malicious".getBytes(StandardCharsets.UTF_8));
        }

        try {
            AgentSpecZipParser.parseAgentSpecFromZip(baos.toByteArray(), NAMESPACE_ID);
            fail("Expected the Windows-drive-path zip to be rejected, but parsing succeeded");
        } catch (SecurityException | NacosApiException e) {
            assertTrue(e.getMessage().contains("Absolute path"));
        }
    }

    @Test
    void testDuplicateNormalizedEntryPathShouldBeRejected() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos, StandardCharsets.UTF_8)) {
            addZipEntry(zos, "manifest.json", VALID_MANIFEST.getBytes(StandardCharsets.UTF_8));
            addZipEntry(zos, "config/file.txt", "first".getBytes(StandardCharsets.UTF_8));
            addZipEntry(zos, "./config/file.txt", "second".getBytes(StandardCharsets.UTF_8));
        }

        try {
            AgentSpecZipParser.parseAgentSpecFromZip(baos.toByteArray(), NAMESPACE_ID);
            fail("Expected duplicate normalized entry paths to be rejected, but parsing succeeded");
        } catch (NacosApiException e) {
            assertTrue(e.getMessage().contains("duplicate entry path"));
        }
    }

    // ---- Test 2: zip bomb (decompressed-size attack) ----

    @Test
    void testZipBombShouldBeRejected() throws IOException {
        // Build a zip whose decompressed size is huge: 110 entries x 1 MB = 110 MB,
        // which exceeds the 50 MB MAX_TOTAL_UNCOMPRESSED_BYTES limit inside the parser.
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos, StandardCharsets.UTF_8)) {
            addZipEntry(zos, "manifest.json", VALID_MANIFEST.getBytes(StandardCharsets.UTF_8));
            // Create many large entries.
            byte[] largeContent = new byte[1024 * 1024]; // 1 MB of zeros (compresses extremely well).
            for (int i = 0; i < 110; i++) {
                addZipEntry(zos, "config/large_file_" + i + ".txt", largeContent);
            }
        }
        byte[] zipBytes = baos.toByteArray();

        try {
            AgentSpecZipParser.parseAgentSpecFromZip(zipBytes, NAMESPACE_ID);
            fail("Expected the zip bomb to be rejected, but parsing succeeded (security hole!)");
        } catch (NacosApiException e) {
            // Verify the rejection reason is the decompressed-size limit.
            boolean isDecompressSizeError = e.getMessage().contains("decompressed size")
                || e.getMessage().contains("exceeds limit");
            boolean isZipSizeError = e.getMessage().contains("must not exceed");
            assertTrue(isDecompressSizeError || isZipSizeError,
                "Expected rejection due to the decompressed-size limit, actual error: "
                    + e.getMessage());
            System.out.println("[PASS] Zip-bomb attack correctly rejected: " + e.getMessage());
        } catch (Exception e) {
            // OutOfMemoryError or any other exception means the guard is missing.
            fail("Zip bomb was not properly guarded, unexpected exception: "
                + e.getClass().getName() + ": " + e.getMessage());
        }
    }

    // ---- Test 3: entry-count attack ----

    @Test
    void testTooManyEntriesShouldBeRejected() throws IOException {
        // Build a zip with more than 500 entries (the MAX_ZIP_ENTRIES cap).
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos, StandardCharsets.UTF_8)) {
            addZipEntry(zos, "manifest.json", VALID_MANIFEST.getBytes(StandardCharsets.UTF_8));
            byte[] smallContent = "x".getBytes(StandardCharsets.UTF_8);
            for (int i = 0; i < 600; i++) {
                addZipEntry(zos, "config/entry_" + i + ".txt", smallContent);
            }
        }
        byte[] zipBytes = baos.toByteArray();

        try {
            AgentSpecZipParser.parseAgentSpecFromZip(zipBytes, NAMESPACE_ID);
            fail(
                "Expected the too-many-entries zip to be rejected, but parsing succeeded (security hole!)");
        } catch (NacosApiException e) {
            boolean isEntryCountError = e.getMessage().contains("too many entries")
                || e.getMessage().contains("max");
            assertTrue(isEntryCountError,
                "Expected rejection due to the entry-count limit, actual error: " + e.getMessage());
            System.out.println("[PASS] Entry-count attack correctly rejected: " + e.getMessage());
        }
    }

    // ---- Helpers ----

    private static void addZipEntry(ZipOutputStream zos, String name, byte[] data)
        throws IOException {
        ZipEntry entry = new ZipEntry(name);
        zos.putNextEntry(entry);
        zos.write(data);
        zos.closeEntry();
    }
}

/**
 * Property-based tests for AgentSpec detail page layout alignment.
 *
 * These tests read the actual source code and verify CSS class patterns
 * to ensure layout consistency with the MCP detail page.
 */
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import fs from 'fs';
import path from 'path';

const SOURCE = fs.readFileSync(
  path.resolve(__dirname, '../../agentSpecDetail/index.tsx'),
  'utf-8',
);

// ── Helpers ────────────────────────────────────────────────────────────────

/**
 * Extract all Card element blocks from the source.
 * Matches `<Card className="...">` and captures the className value.
 */
function extractCardClassNames(src: string): string[] {
  const re = /<Card\s+className="([^"]+)"/g;
  const results: string[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(src)) !== null) {
    results.push(m[1]);
  }
  return results;
}

/**
 * Extract all card header div blocks — the `<div className="...">` that
 * immediately follow a `<Card` opening and contain `border-b`.
 * We look for divs with className containing both `border-b` and `bg-muted`.
 */
function extractCardHeaderClassNames(src: string): string[] {
  const re = /<div\s+className="([^"]*border-b[^"]*)"/g;
  const results: string[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(src)) !== null) {
    results.push(m[1]);
  }
  return results;
}

/**
 * Extract all card header title elements — `<h2 className="...">` inside
 * card headers.
 */
function extractCardTitleClassNames(src: string): string[] {
  const re = /<h2\s+className="([^"]+)"/g;
  const results: string[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(src)) !== null) {
    results.push(m[1]);
  }
  return results;
}

// ── Pre-extracted data ─────────────────────────────────────────────────────

const cardClassNames = extractCardClassNames(SOURCE);
const cardHeaderClassNames = extractCardHeaderClassNames(SOURCE);
const cardTitleClassNames = extractCardTitleClassNames(SOURCE);

// ── Task 6.1: Property 1 — Card style consistency ─────────────────────────

/**
 * Property 1: 卡片样式一致性
 *
 * For all Card elements in the AgentSpec detail page, each Card must contain
 * `overflow-hidden`, `py-0`, and `gap-0` classes. Each card header must
 * contain `border-b` and `bg-muted/30`. Each card title must contain
 * `text-sm` and `font-semibold`.
 *
 * **Validates: Requirements 5.1, 5.2, 5.3**
 */
describe('Property 1: 卡片样式一致性 (Card style consistency)', () => {
  const REQUIRED_CARD_CLASSES = ['overflow-hidden', 'py-0', 'gap-0'];
  const REQUIRED_HEADER_CLASSES = ['border-b', 'bg-muted/30'];
  const REQUIRED_TITLE_CLASSES = ['text-sm', 'font-semibold'];

  it('should have at least one Card element in the source', () => {
    expect(cardClassNames.length).toBeGreaterThan(0);
  });

  it('property: every Card contains all required card classes', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(...REQUIRED_CARD_CLASSES),
        (requiredClass) => {
          for (const cn of cardClassNames) {
            expect(cn).toContain(requiredClass);
          }
        },
      ),
      { numRuns: REQUIRED_CARD_CLASSES.length * 5 },
    );
  });

  it('property: every card header contains all required header classes', () => {
    // Filter to only headers inside the content grid (those with bg-muted/30)
    const contentHeaders = cardHeaderClassNames.filter((cn) =>
      cn.includes('bg-muted'),
    );
    expect(contentHeaders.length).toBeGreaterThan(0);

    fc.assert(
      fc.property(
        fc.constantFrom(...REQUIRED_HEADER_CLASSES),
        (requiredClass) => {
          for (const cn of contentHeaders) {
            expect(cn).toContain(requiredClass);
          }
        },
      ),
      { numRuns: REQUIRED_HEADER_CLASSES.length * 5 },
    );
  });

  it('property: every card title contains all required title classes', () => {
    expect(cardTitleClassNames.length).toBeGreaterThan(0);

    fc.assert(
      fc.property(
        fc.constantFrom(...REQUIRED_TITLE_CLASSES),
        (requiredClass) => {
          for (const cn of cardTitleClassNames) {
            expect(cn).toContain(requiredClass);
          }
        },
      ),
      { numRuns: REQUIRED_TITLE_CLASSES.length * 5 },
    );
  });

  it('property: random subsets of required card classes all appear in every Card', () => {
    fc.assert(
      fc.property(
        fc.subarray(REQUIRED_CARD_CLASSES, { minLength: 1 }),
        (subset) => {
          for (const cn of cardClassNames) {
            for (const cls of subset) {
              expect(cn).toContain(cls);
            }
          }
        },
      ),
      { numRuns: 50 },
    );
  });
});

// ── Task 6.2: Property 2 — Layout structure consistency ───────────────────

/**
 * Property 2: 布局结构一致性
 *
 * For any rendering state (loading or loaded), the content grid must use
 * a two-column desktop layout with a flexible primary pane and a fixed-width
 * 320px right rail, ensuring the IDE expands to consume all remaining space.
 *
 * **Validates: Requirements 2.1, 2.2, 2.3, 6.1**
 */
describe('Property 2: 布局结构一致性 (Layout structure consistency)', () => {
  const REQUIRED_GRID_CLASSES = ['lg:grid-cols-[minmax(0,1fr)_320px]'];
  const REQUIRED_RIGHT_COL_CLASSES = ['lg:w-[320px]'];

  // Split source into loading skeleton section and loaded section
  const skeletonSectionMatch = SOURCE.match(
    /\/\/\s*=+\s*Loading skeleton\s*=+[\s\S]*?return\s*\(\s*([\s\S]*?)\s*\);\s*\}/,
  );
  const skeletonSection = skeletonSectionMatch
    ? skeletonSectionMatch[1]
    : '';

  // Alternatively, find the content grid in the main return
  const contentGridSection = SOURCE.slice(
    SOURCE.indexOf('Content Grid'),
  );

  it('should find the loading skeleton section', () => {
    expect(skeletonSection.length).toBeGreaterThan(0);
  });

  it('loading skeleton uses the fixed-width right rail grid', () => {
    expect(skeletonSection).toContain('lg:grid-cols-[minmax(0,1fr)_320px]');
  });

  it('loaded state uses the fixed-width right rail grid', () => {
    expect(contentGridSection).toContain('lg:grid-cols-[minmax(0,1fr)_320px]');
  });

  it('loaded state keeps the right rail at 320px', () => {
    expect(contentGridSection).toContain('lg:w-[320px]');
  });

  it('property: both skeleton and loaded state contain all required grid classes', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(...REQUIRED_GRID_CLASSES),
        (requiredClass) => {
          expect(skeletonSection).toContain(requiredClass);
          expect(contentGridSection).toContain(requiredClass);
        },
      ),
      { numRuns: REQUIRED_GRID_CLASSES.length * 5 },
    );
  });

  it('property: loaded state contains all required right rail classes', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(...REQUIRED_RIGHT_COL_CLASSES),
        (requiredClass) => {
          expect(contentGridSection).toContain(requiredClass);
        },
      ),
      { numRuns: REQUIRED_RIGHT_COL_CLASSES.length * 5 },
    );
  });

  it('property: random subsets of desktop layout classes all appear where expected', () => {
    const ALL_LAYOUT_CLASSES = [
      ...REQUIRED_GRID_CLASSES,
      ...REQUIRED_RIGHT_COL_CLASSES,
    ];

    fc.assert(
      fc.property(
        fc.subarray(ALL_LAYOUT_CLASSES, { minLength: 1 }),
        (subset) => {
          for (const cls of subset) {
            if (REQUIRED_GRID_CLASSES.includes(cls)) {
              expect(skeletonSection).toContain(cls);
            }
            expect(contentGridSection).toContain(cls);
          }
        },
      ),
      { numRuns: 50 },
    );
  });
});

import { useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { agentSpecApi } from '@/api/agentspec';

interface CreateAgentSpecDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  namespaceId: string;
  onSuccess: (agentSpecName: string) => void;
}

export function CreateAgentSpecDialog({
  open,
  onOpenChange,
  namespaceId,
  onSuccess,
}: CreateAgentSpecDialogProps) {
  const { t } = useTranslation();

  const [agentSpecName, setAgentSpecName] = useState('');
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleClose = useCallback(
    (nextOpen: boolean) => {
      if (!nextOpen) {
        setAgentSpecName('');
        setDescription('');
        setError(null);
        setLoading(false);
      }
      onOpenChange(nextOpen);
    },
    [onOpenChange],
  );

  const handleCreate = useCallback(async () => {
    const trimmedName = agentSpecName.trim();
    if (!trimmedName) {
      setError(t('agentSpec.nameRequired'));
      return;
    }
    if (!description.trim()) {
      setError(t('agentSpec.descriptionRequired'));
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const agentSpecCard = JSON.stringify({
        name: trimmedName,
        description: description.trim(),
        content: '',
        resource: {},
      });
      await agentSpecApi.updateDraft({ namespaceId, agentSpecCard });
      toast.success(t('agentSpec.createSuccess'));
      handleClose(false);
      onSuccess(trimmedName);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : t('agentSpec.createFailed');
      setError(msg);
    } finally {
      setLoading(false);
    }
  }, [agentSpecName, description, namespaceId, t, handleClose, onSuccess]);

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>{t('agentSpec.createAgentSpec')}</DialogTitle>
          <DialogDescription>{t('agentSpec.createAgentSpecDesc')}</DialogDescription>
        </DialogHeader>

        <div className="space-y-4 pt-2">
          <div className="space-y-2">
            <Label htmlFor="agentspec-name">{t('agentSpec.agentSpecName')} *</Label>
            <Input
              id="agentspec-name"
              placeholder={t('agentSpec.namePlaceholder')}
              value={agentSpecName}
              onChange={(e) => {
                setAgentSpecName(e.target.value);
                setError(null);
              }}
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="agentspec-desc">{t('agentSpec.description')} *</Label>
            <Textarea
              id="agentspec-desc"
              placeholder={t('agentSpec.descriptionPlaceholder')}
              value={description}
              onChange={(e) => {
                setDescription(e.target.value);
                setError(null);
              }}
              className="min-h-24 resize-y"
            />
          </div>

          {error && <p className="text-sm text-destructive">{error}</p>}

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => handleClose(false)}
              disabled={loading}
            >
              {t('common.cancel')}
            </Button>
            <Button
              onClick={handleCreate}
              disabled={!agentSpecName.trim() || !description.trim() || loading}
            >
              {loading ? t('common.loading') : t('agentSpec.createAgentSpec')}
            </Button>
          </DialogFooter>
        </div>
      </DialogContent>
    </Dialog>
  );
}

